 public UUID owner,encounter;public boolean lastStand,lethalUsed;private int morphPhase=-1;private long birdStarted,curseUntil,markUntil;private UUID marked;private Vec3 leapFrom,leapTo;private LivingEntity committed;private long restSince;private int stuck;
