 public UUID syncedOwner(){return entityData.get(OWNER).orElse(null);}public boolean recovering(){return entityData.get(REST);}public boolean morphed(){return entityData.get(MORPH);}public int bird(){return entityData.get(BIRD);}public float birdAge(float p){return level().getGameTime()-entityData.get(BIRD_START)+p;}public int birdTarget(){return entityData.get(BIRD_TARGET);}public int markTarget(){return entityData.get(MARK);}public int anchorId(){return entityData.get(ANCHOR);}public int[] watchIds(){return new int[]{entityData.get(WATCH1),entityData.get(WATCH2),entityData.get(WATCH3)};}
