 public boolean evade(DamageSource s){if(action()==FalconAction.MORPH&&age()>=4&&age()<12&&s.getDirectEntity() instanceof org.slavicmyths.kalin.KalinEntity&&s.is(net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.DAMAGE_TYPE,org.slavicmyths.kalin.KalinContent.id("kalin_sabre"))))return true;return action()==FalconAction.MORPH&&age()>=4&&age()<12&&s.getDirectEntity() instanceof KartausEntity&&!(s.is(net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.DAMAGE_TYPE,FinistContent.id("kartaus_eye")))||s.is(net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.DAMAGE_TYPE,FinistContent.id("kartaus_chains"))));}
 public boolean guard(DamageSource s,ServerPlayer p){if(cursed()||recovering()||morphed()||!ready("guard")||!Objects.equals(owner,p.getUUID())||distanceTo(p)>12)return false;var direct=s.getDirectEntity();if(direct instanceof org.slavicmyths.kalin.KalinEntity k&&org.slavicmyths.kalin.KalinParty.allowed(this,k)&&s.is(net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.DAMAGE_TYPE,org.slavicmyths.kalin.KalinContent.id("kalin_sabre")))&&hasLineOfSight(k)){cooldown("guard",240);bird(3,k);cue("entity.falcon.intercept");return true;}if(direct instanceof KartausEntity k&&s.is(net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.DAMAGE_TYPE,FinistContent.id("kartaus_melee")))&&hasLineOfSight(k)){cooldown("guard",240);bird(3,k);cue("entity.falcon.intercept");return true;}if(!(direct instanceof net.minecraft.world.entity.projectile.Projectile pr)||!(pr.getOwner() instanceof Monster)||!hasLineOfSight(pr))return false;cooldown("guard",240);pr.discard();bird(3,null);cue("entity.falcon.intercept");return true;}
 public void retreat(){if(lastStand)return;lastStand=true;entityData.set(REST,true);restSince=level().getGameTime();var b=boss();if(b!=null){b.releaseCurse(false);var e=KartausEncounter.get((ServerLevel)level()).entries.get(encounter);if(e!=null){e.retreated=true;KartausEncounter.get((ServerLevel)level()).setDirty();}var dir=position().subtract(b.position()).multiply(1,0,1).normalize();if(dir.lengthSqr()<.1)dir=heading();var at=KartausEncounter.ground((ServerLevel)level(),b.position().add(dir.scale(20)),.76,2.25);if(at!=null)getNavigation().moveTo(at.x,at.y,at.z,1.25);}
 clearCurse();entityData.set(MORPH,false);begin(FalconAction.RETREAT);if(b!=null){var dir=position().subtract(b.position()).multiply(1,0,1).normalize();var at=KartausEncounter.ground((ServerLevel)level(),b.position().add(dir.scale(20)),.76,2.25);if(at!=null)getNavigation().moveTo(at.x,at.y,at.z,1.25);}cue("entity.finist.retreat");var p=player();if(p!=null)KartausEncounter.msg(p,"finist_retreat");}
 private void recover(){setTarget(null);var b=boss();if(b!=null&&distanceTo(b)<16){if(level().getGameTime()-restSince>100){HeroCalls.sleepFinist(this);}return;}if(action()==FalconAction.RETREAT&&age()<26)return;getNavigation().stop();if(action()!=FalconAction.DRINK)begin(FalconAction.DRINK);if(tickCount%20==0&&getHealth()<119){heal(8);cue("entity.finist.tonic");}if(b==null&&getHealth()>=119){entityData.set(REST,false);lastStand=false;begin(FalconAction.IDLE);}}
 private boolean leap(LivingEntity t,boolean morph){if(!(level() instanceof ServerLevel w))return false;var d=t.position().subtract(position()).multiply(1,0,1);if(d.lengthSqr()<.1)return false;double travel=Math.min(6,d.length()+1);var at=KartausEncounter.ground(w,position().add(d.normalize().scale(travel)),.76,2.25);if(at==null)return false;for(int n=1;n<=10;n++){double f=n/10D;var q=position().lerp(at,f).add(0,Math.sin(f*Math.PI)*2.6,0);if(!w.noCollision(getBoundingBox().move(q.subtract(position()))))return false;}leapFrom=position();leapTo=at;committed=t;begin(morph?FalconAction.MORPH:FalconAction.DASH);cue(morph?"entity.finist.transform":"entity.finist.wing_dash");cooldown(morph?"morph":"dash",morph?600:180);if(morph){var b=boss();morphPhase=b==null?0:b.phase;bird(5,null);}return true;}
 private void leapTick(){boolean morph=action()==FalconAction.MORPH;if(morph&&frame(12))entityData.set(MORPH,true);int from=morph?12:4,to=morph?32:21;if(age()>=from&&age()<=to&&leapFrom!=null&&leapTo!=null){double f=(age()-from)/(double)(to-from);var q=leapFrom.lerp(leapTo,f).add(0,Math.sin(f*Math.PI)*2.6,0);var delta=q.subtract(position());if(level().noCollision(getBoundingBox().move(delta)))move(MoverType.SELF,delta);fallDistance=0;setDeltaMovement(Vec3.ZERO);if(frame(to-1)&&allowed(committed)&&edge(committed)<2.7&&hasLineOfSight(committed))committed.hurt(damageSources().mobAttack(this),morph?7:8);}
 if(morph&&frame(33)){if(level() instanceof ServerLevel w&&!HeroCalls.safeSpot(w,position(),.76,2.25)){var at=KartausEncounter.ground(w,leapFrom,.76,2.25);if(at!=null)setPos(at);}entityData.set(MORPH,false);bird(0,null);}}
 private void controller(ServerPlayer p){if(cursed())return;if(bird()==1){if(tickCount%20==0){var list=level().getEntitiesOfClass(LivingEntity.class,p.getBoundingBox().inflate(20,8,20),this::allowed).stream().filter(this::hasLineOfSight).sorted(Comparator.comparingDouble(this::distanceToSqr)).limit(3).toList();EntityDataAccessor<Integer>[] ids=new EntityDataAccessor[]{WATCH1,WATCH2,WATCH3};for(int n=0;n<3;n++)entityData.set(ids[n],n<list.size()?list.get(n).getId():0);}if(level().getGameTime()-birdStarted>=100){bird(0,null);entityData.set(WATCH1,0);entityData.set(WATCH2,0);entityData.set(WATCH3,0);cooldown("watch",120);}}
 else if(bird()==2){if(birdAge(0)==16&&level().getEntity(entityData.get(BIRD_TARGET)) instanceof LivingEntity t&&allowed(t)&&hasLineOfSight(t)&&distanceTo(t)<=20){t.hurt(damageSources().mobAttack(this),t instanceof KartausEntity||t instanceof org.slavicmyths.kalin.KalinEntity?2:3);if(t instanceof Monster m)m.getPersistentData().putLong("FinistDistractedUntil",level().getGameTime()+35);cue("entity.falcon.dive_impact");}if(birdAge(0)>=26)bird(0,null);}else if(bird()==3&&birdAge(0)>=25)bird(0,null);
 }
 @Override public void tick(){super.tick();if(!(level() instanceof ServerLevel w))return;if(tickCount==1)cue("entity.finist.summon_chime");entityData.set(OWNER,Optional.ofNullable(owner));var p=player();if(p==null||!p.isAlive()||p.isSpectator()||p.serverLevel()!=w){setTarget(null);getNavigation().stop();if(cursed()||bird()!=0)clearCurse();entityData.set(MORPH,false);return;}if(owner!=null&&!getUUID().equals(HeroCalls.map(w,"finist").get(owner))){discard();return;}
 if(org.slavicmyths.kalin.KalinParty.prepare(this,owner))return;if(encounter!=null&&!KartausEncounter.get(w).active(encounter)){encounter=null;clearCurse();}if(getPersistentData().getBoolean("HeroRecalling")||w.getGameTime()<getPersistentData().getLong("HeroArrivingUntil"))return;if(encounter==null&&org.slavicmyths.marinka.StoryPolicy.standby(owner,w)){setTarget(null);getNavigation().stop();return;}
 if(curseUntil>0&&w.getGameTime()>=curseUntil){if(boss()!=null)boss().releaseCurse(false);else clearCurse();}if(w.getGameTime()>=markUntil){marked=null;entityData.set(MARK,0);}if(recovering()){recover();return;}if(getHealth()<=25.5F&&!lastStand){retreat();return;}controller(p);
 if(tickCount%20==0){var b=boss();LivingEntity t=b;if(t==null)t=org.slavicmyths.kalin.KalinParty.target(this,p);if(b!=null){if(b.anchor()!=null)t=b.anchor();else if(b.bannerCount()>0)t=b.closestBanner();}if(t==null)t=org.slavicmyths.bogatyr.HeroThreats.nearest(this,p,20);setTarget(t);}
 var kb=org.slavicmyths.kalin.KalinParty.commander(this);if(kb!=null&&getHealth()<76.5&&ready("morph")&&morphPhase!=kb.phase()&&(kb.action()==FalconAction.WAVE||kb.action()==FalconAction.DASH)&&kb.age()<12&&!cursed()&&action()!=FalconAction.MORPH&&leap(kb,true)){morphPhase=kb.phase();return;}
 var t=getTarget();if(t!=null&&!allowed(t)){setTarget(null);t=null;}var b=boss();if(b!=null&&getHealth()<76.5&&ready("morph")&&morphPhase!=b.phase&&(b.action()==FalconAction.EYE||b.action()==FalconAction.WAVE)&&b.age()<12&&!cursed()&&action()!=FalconAction.MORPH){if(leap(b,true))return;}
 if(action()!=FalconAction.IDLE){if(action()==FalconAction.DASH||action()==FalconAction.MORPH)leapTick();if(action()==FalconAction.SWORD&&frame(8)&&allowed(committed)&&cone(committed,2.7,95)&&hasLineOfSight(committed)){if(committed.hurt(damageSources().mobAttack(this),5))playSound(FinistContent.sound("entity.finist.sword_contact"),.8F,1);}if(action()==FalconAction.MARK&&frame(12)&&allowed(committed)&&distanceTo(committed)<=20&&hasLineOfSight(committed)&&!cursed()){marked=committed.getUUID();markUntil=w.getGameTime()+120;entityData.set(MARK,committed.getId());}if(action()==FalconAction.INSPIRE&&frame(15)&&distanceTo(p)<=12){p.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SPEED,100,0));for(String id:List.of("ilya_muromets","dobrynya_nikitich","alyosha_popovich")){var ally=HeroCalls.loaded(p,id);if(ally instanceof LivingEntity a&&a.level()==w&&distanceTo(a)<=12)a.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SPEED,100,0));}}
 if(age()>=duration())begin(FalconAction.IDLE);return;}
 if(t!=null){face(t);if(!cursed()&&bird()==0&&ready("watch")){bird(1,t);cue("entity.falcon.scout_call");}if(!cursed()&&ready("mark")&&marked==null&&hasLineOfSight(t)){committed=t;begin(FalconAction.MARK);cooldown("mark",240);cue("entity.finist.mark_cast");return;}
 if(ready("inspire")&&(p.getHealth()<p.getMaxHealth()*.6||(t instanceof KartausEntity||t instanceof org.slavicmyths.kalin.KalinEntity))){begin(FalconAction.INSPIRE);cooldown("inspire",400);cue("entity.finist.inspire");return;}
 if(!cursed()&&bird()==0&&ready("birdDive")&&distanceTo(t)>=8&&distanceTo(t)<=17&&hasLineOfSight(t)){bird(2,t);cooldown("birdDive",140);cue("entity.falcon.dive_start");}if(distanceTo(t)>=3&&distanceTo(t)<=9&&ready("dash")&&!(t instanceof BannerEntity)&&leap(t,false))return;
 if(edge(t)<=2.7&&ready("sword")&&hasLineOfSight(t)){committed=t;begin(FalconAction.SWORD);cooldown("sword",30);cue("entity.finist.sword_swing_1");}else if(tickCount%10==0)getNavigation().moveTo(t,1);}
 else if(tickCount%10==0){if(distanceTo(p)>7)getNavigation().moveTo(p,1);else getNavigation().stop();if(distanceTo(p)>12&&getDeltaMovement().horizontalDistanceSqr()<.0001)stuck+=10;else stuck=0;if(stuck>80&&encounter==null){var at=org.slavicmyths.bogatyr.BogatyrLedger.safe(w,p.position(),.76,3,4);if(HeroCalls.safeSpot(w,at,.76,2.25)){setPos(at);stuck=0;}}}
 var motion=getDeltaMovement();if(motion.horizontalDistance()>.30)setDeltaMovement(motion.multiply(.30/motion.horizontalDistance(),1,.30/motion.horizontalDistance()));}
 @Override protected net.minecraft.sounds.SoundEvent getHurtSound(DamageSource s){return FinistContent.sound("entity.finist.hurt_"+(1+random.nextInt(3)));}
 @Override protected void playStepSound(net.minecraft.core.BlockPos p,net.minecraft.world.level.block.state.BlockState state){if(!level().isClientSide)playSound(FinistContent.sound("entity.finist.run_step_"+(1+random.nextInt(2))),.3F,1);}
 @Override public void die(DamageSource s){if(level() instanceof ServerLevel w&&owner!=null){HeroCalls.map(w,"finist").remove(owner,getUUID());HeroCalls.dirty(w);if(encounter!=null){var e=KartausEncounter.get(w).entries.get(encounter);if(e!=null)KartausEncounter.get(w).finish(w,e,false);}}super.die(s);}
 @Override public void addAdditionalSaveData(CompoundTag n){super.addAdditionalSaveData(n);if(owner!=null)n.putUUID("FinistOwner",owner);if(encounter!=null)n.putUUID("FinistEncounter",encounter);n.putBoolean("FinistRest",recovering());n.putBoolean("FinistLastStand",lastStand);n.putBoolean("FinistLethalUsed",lethalUsed);n.putLong("FinistRestSince",restSince);n.putInt("FinistMorphPhase",morphPhase);}
 @Override public void readAdditionalSaveData(CompoundTag n){super.readAdditionalSaveData(n);owner=n.hasUUID("FinistOwner")?n.getUUID("FinistOwner"):null;encounter=n.hasUUID("FinistEncounter")?n.getUUID("FinistEncounter"):null;lastStand=n.getBoolean("FinistLastStand");lethalUsed=n.getBoolean("FinistLethalUsed");restSince=n.getLong("FinistRestSince");morphPhase=n.getInt("FinistMorphPhase");entityData.set(OWNER,Optional.ofNullable(owner));entityData.set(REST,n.getBoolean("FinistRest"));entityData.set(MORPH,false);clearCurse();}
